231	func extractTarGz(r io.Reader) (map[string]string, error) {
232		gzr, err := gzip.NewReader(r)
233		if err != nil {
234			return nil, err
235		}
236		defer func() { _ = gzr.Close() }()
237	
238		tr := tar.NewReader(gzr)
239		files := make(map[string]string)
240	
241		for {
242			header, err := tr.Next()
243			if err == io.EOF {
244				break
245			}
246			if err != nil {
247				return nil, err
248			}
249	
250			// Skip directories
251			if header.Typeflag == tar.TypeDir {
252				continue
253			}
254	
255			// Read file content
256			content, err := io.ReadAll(tr)
257			if err != nil {
258				return nil, err
259			}
260	
261			// Clean path (remove leading ./ or /)
262			path := strings.TrimPrefix(header.Name, "./")
263			path = strings.TrimPrefix(path, "/")
264	
265			files[path] = string(content)
266		}
267	
268		return files, nil
269	}
