53	
54		countInput := textinput.New()
55		countInput.Placeholder = "4"
56		countInput.CharLimit = 2
57		countInput.Width = 10
58	
59		nsInput := textinput.New()
60		nsInput.Placeholder = "8.8.8.8 (optional)"
61		nsInput.CharLimit = 50
62		nsInput.Width = 40
63	
64		// Apply theme background to all textinputs
65		theme.StyleTextInput(&nameInput)
66		theme.StyleTextInput(&targetInput)
67		theme.StyleTextInput(&timeoutInput)
68		theme.StyleTextInput(&countInput)
69		theme.StyleTextInput(&nsInput)
70	
71		form := &ComponentForm{
72			nameInput:    nameInput,
73			targetInput:  targetInput,
74			timeoutInput: timeoutInput,
75			countInput:   countInput,
76			nsInput:      nsInput,
77			focusIndex:   0,
78			compType:     "https",
79			editing:      component != nil,
80		}
81	
82		// Si édition, pré-remplir les champs
83		if component != nil {
84			form.original = component
85			form.nameInput.SetValue(component.Name)
86			form.targetInput.SetValue(component.Target)
87			if component.Timeout > 0 {
88				form.timeoutInput.SetValue(fmt.Sprintf("%d", component.Timeout))
