113	// Update met à jour le formulaire
114	func (f *ComponentForm) Update(msg tea.Msg) (*ComponentForm, tea.Cmd) {
115		switch msg := msg.(type) {
116		case tea.WindowSizeMsg:
117			f.width = msg.Width
118			f.height = msg.Height
119		case tea.KeyMsg:
120			return f.handleKeyMsg(msg)
121		}
122	
123		return f, f.updateActiveInput(msg)
124	}
