161	// navigateField moves focus by delta (+1 or -1) with wrapping
162	func (f *ComponentForm) navigateField(delta int) {
163		maxIndex := f.maxFieldIndex()
164		f.focusIndex += delta
165		if f.focusIndex > maxIndex {
166			f.focusIndex = 0
167		}
168		if f.focusIndex < 0 {
169			f.focusIndex = maxIndex
170		}
171		f.updateFocus()
172	}
