182	// submitForm valide et soumet le formulaire
183	func (f *ComponentForm) submitForm() (*ComponentForm, tea.Cmd) {
184		name := strings.TrimSpace(f.nameInput.Value())
185		target := strings.TrimSpace(f.targetInput.Value())
186		if name == "" || target == "" {
187			return f, nil
188		}
189	
190		component := config.ComponentConfig{
191			Name:    name,
192			Type:    f.compType,
193			Target:  target,
194			Timeout: f.parseTimeout(),
195		}
196	
197		if f.compType == "icmp" {
198			component.Count = f.parseCount()
199		}
200		if f.compType == "dns" {
201			component.Nameserver = strings.TrimSpace(f.nsInput.Value())
202		}
203	
204		return f, func() tea.Msg {
205			return ComponentFormSubmitMsg{
206				Component: component,
207				Original:  f.original,
208			}
209		}
210	}
